import { PluginBase } from "../../core/index.js";
/**
 * Abstract base class for playback plugins.
 *
 * Playback plugins are used to visualize previously captured multimodal sessions in the app.
 *
 * Each plugin provides:
 * - A **preview** for display on the main (home) page, using `getPreview`. This is a static or dynamic representation
 *   (e.g., miniature graph, waveform, or visualization) that gives the user an idea of what the plugin provides.
 *   The preview is rendered based on configurations created for the plugin and is visible before a session is selected for playback.
 *
 * - A **main view** for interactive session playback, using `getView`. This is rendered when the user navigates to a specific session for a project and participant,
 *   and is where full playback occurs (with real data). The view can respond to play, pause, seek, and sync events through the provided controls.
 *
 * Attributes:
 * - `context`: The playback context, including file path and timestamps, injected by the application.
 *
 * Required methods:
 * - `getView(props)`: Renders the main playback UI for visualizing the session (with interactive controls).
 * - `getPreview()`: Renders a preview visualization for the home page or configuration selection.
 * - `validExtensions()`: Returns a list of supported file extensions (e.g., ["mp4", "json"]) for captured session files.
 */
export class PlaybackPlugin extends PluginBase {
    context;
    static __module = "playback";
    /**
     * Validate a capture plugin's output descriptor to decide if this playback
     * plugin can consume the produced artifact.
     *
     * Called by the host when evaluating which playback plugin(s) are compatible
     * with a capture configuration. Plugins can override this static method to
     * implement custom validation logic.
     *
     * @param descriptor - The descriptor object produced by the capture plugin or null if none.
     * @returns boolean - true if this playback plugin accepts the descriptor.
     */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    validateCaptureDescriptor(_descriptor) {
        return true;
    }
}
